package net.minecraft.resources;public final class ResourceLocation {private final String id;public ResourceLocation(String s){id=s.contains(":")?s:"minecraft:"+s;}public static ResourceLocation parse(String s){return new ResourceLocation(s);}public static ResourceLocation tryParse(String s){return s==null||s.isBlank()||s.contains(" ")?null:new ResourceLocation(s);}public String getPath(){return id.substring(id.indexOf(':')+1);}public String getNamespace(){return id.substring(0,id.indexOf(':'));}public String toString(){return id;}public boolean equals(Object o){return o instanceof ResourceLocation r&&id.equals(r.id);}public int hashCode(){return id.hashCode();}}